package com.hbm.machine.gascentrifuge;
import com.hbm.fluid.*;import com.hbm.item.fluid.FluidIconItem;import com.mojang.serialization.*;import com.mojang.serialization.codecs.RecordCodecBuilder;import java.util.*;import net.minecraft.core.*;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.Level;
/** Four original complete-cascade NEI summaries; execution still follows every true stage. */
public record GasCentrifugeRecipe(String fluid,int amount,List<ItemStack> results,boolean highSpeed,int machines) implements Recipe<SingleRecipeInput>{
 public static final MapCodec<GasCentrifugeRecipe> CODEC=RecordCodecBuilder.mapCodec(i->i.group(Codec.STRING.fieldOf("fluid").forGetter(GasCentrifugeRecipe::fluid),Codec.INT.fieldOf("amount").forGetter(GasCentrifugeRecipe::amount),ItemStack.CODEC.listOf().fieldOf("results").forGetter(GasCentrifugeRecipe::results),Codec.BOOL.fieldOf("high_speed").forGetter(GasCentrifugeRecipe::highSpeed),Codec.INT.fieldOf("machines").forGetter(GasCentrifugeRecipe::machines)).apply(i,GasCentrifugeRecipe::new));
 public static final StreamCodec<RegistryFriendlyByteBuf,GasCentrifugeRecipe> STREAM=StreamCodec.of((b,r)->{b.writeUtf(r.fluid);b.writeVarInt(r.amount);b.writeVarInt(r.results.size());for(var s:r.results)ItemStack.STREAM_CODEC.encode(b,s);b.writeBoolean(r.highSpeed);b.writeVarInt(r.machines);},b->{String f=b.readUtf();int a=b.readVarInt(),n=b.readVarInt();var out=new ArrayList<ItemStack>();for(int j=0;j<n;j++)out.add(ItemStack.STREAM_CODEC.decode(b));return new GasCentrifugeRecipe(f,a,out,b.readBoolean(),b.readVarInt());});
 public GasCentrifugeRecipe{results=List.copyOf(results);}public ItemStack input(){return FluidIconItem.make(HbmFluids.fromNameCompat(fluid),amount);}@Override public boolean matches(SingleRecipeInput input,Level level){return false;}@Override public ItemStack assemble(SingleRecipeInput input,HolderLookup.Provider lookup){return results.getFirst().copy();}@Override public ItemStack getResultItem(HolderLookup.Provider lookup){return results.getFirst();}@Override public boolean canCraftInDimensions(int w,int h){return true;}@Override public boolean isSpecial(){return true;}@Override public RecipeType<?> getType(){return GasCentrifugeContent.TYPE.get();}@Override public RecipeSerializer<?> getSerializer(){return GasCentrifugeContent.SERIALIZER.get();}@Override public ItemStack getToastSymbol(){return new ItemStack(GasCentrifugeContent.ITEM.get());}
 public static final class Serializer implements RecipeSerializer<GasCentrifugeRecipe>{@Override public MapCodec<GasCentrifugeRecipe> codec(){return CODEC;}@Override public StreamCodec<RegistryFriendlyByteBuf,GasCentrifugeRecipe> streamCodec(){return STREAM;}}
}
